<script setup>
import { useAuthStore } from '@/stores/auth'
import { ref } from 'vue'
const authStore = useAuthStore()


defineProps({
    id: Number,
    image: String,
    image2x: String,
    title: String,
    description: String,
    isFavorite: Boolean,
    dinoPageId: Number
})

const getImage = (value) => {
    if (!value) return ''

    // Cloudinary URL
    if (value.startsWith('http')) {
        return value
    }

    // локальные картинки проекта
    return new URL(`../images/${value}`, import.meta.url).href
}

const liked = ref(props.isFavorite === 'liked')

const btnLiked = async (event) => {
    event.preventDefault()

    try {
        const newStatus =
            liked.value
                ? 'none'
                : 'liked'

        await api.put(
            `/dinoCard/favorite/${props.id}`,
            {
                favorite_status: newStatus
            }
        )

        liked.value = !liked.value

    } catch (err) {
        console.error(err)
    }
}
</script>

<template>
    <div class="card-comp">
        <RouterLink class="card" :to="`/dino/${dinoPageId}`">
            <div class="card__img-wrap">
                <img v-if="image" :src="getImage(image)" :srcset="image2x ? `${getImage(image2x)} 2x` : ''"
                    class="card__img" alt="картинка карточки" />
                <span class="card__hover">Читать</span>
            </div>
            <div class="card-content">
                <h2 class="card-content__title">{{ title }}</h2>
                <p class="card-content__descr">{{ description }}</p>
            </div>
            <slot></slot>
        </RouterLink>
        <button @click.stop="btnLiked" :class="['card__like', { clicked: liked }]">
